import io, pikepdf
from reportlab.lib.pagesizes import A4
from reportlab.lib.units import mm
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle as PS
from reportlab.platypus import SimpleDocTemplate, Paragraph as P, Spacer, Table, TableStyle
H1=PS('h1',fontName='Helvetica-Bold',fontSize=13,leading=16,spaceAfter=3)
H2=PS('h2',fontName='Helvetica-Bold',fontSize=10.6,leading=14,spaceBefore=11,spaceAfter=4)
B=PS('b',fontName='Helvetica',fontSize=9.5,leading=13,spaceAfter=7)
BL=PS('bl',fontName='Helvetica',fontSize=9.5,leading=13,spaceAfter=6,leftIndent=9*mm,firstLineIndent=-5*mm)
SM=PS('sm',fontName='Helvetica',fontSize=8.3,leading=10.5)
SMB=PS('smb',fontName='Helvetica-Bold',fontSize=8.3,leading=10.5)
s=[]
s.append(P('NOTICE OF DISPUTE — STAGE 2',H1))
s.append(P('Clause 1.11.2(b), Queensland Public Health Sector Certified Agreement (No. 12) 2025',SM))
s.append(Spacer(1,7))
r=[[P('<b>To</b>',SMB),P('Ms Noelle Cridland, Health Service Chief Executive, Metro South Health — as the appropriate management representative under clause 1.11.2(b), for the reasons at paragraph 2',SM)],
   [P('<b>Copied to</b>',SMB),P('Ms Jacqui Roberts, Principal Consultant, Human Resources, Logan and Beaudesert Health Service · Ms Emily Petering, Together Queensland · Metro South Correspondence',SM)],
   [P('<b>Employee</b>',SMB),P('Cory Shepherd, employee number 388372 — AO3, Switchboard Services, Logan Hospital. Permanent full-time, 76 hours per fortnight. Together Queensland member and endorsed workplace delegate.',SM)],
   [P('<b>Date</b>',SMB),P('7 September 2026',SM)],
   [P('<b>Matter</b>',SMB),P('Attendance, roster, leave and pay from 26 June 2026 (MSH-INJ-5795)',SM)]]
t=Table(r,colWidths=[24*mm,146*mm])
t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),0.4,colors.HexColor('#999999')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),3),('RIGHTPADDING',(0,0),(-1,-1),3),('TOPPADDING',(0,0),(-1,-1),2.5),('BOTTOMPADDING',(0,0),(-1,-1),2.5)]))
s.append(t)

s.append(P('1. THE REFERRAL',H2))
s.append(P('I refer this dispute to Stage 2 under clause 1.11.2(b) of the Agreement, and ask that a conference of the parties be arranged. I ask that Together Queensland attend with me.',B))
s.append(P('A Stage 1 notice was given on 3 August 2026. On 4 August 2026 Ms Taylor acknowledged that the 24-hour requirement in clause 1.11.2(a) "will not be achieved", confirmed the dispute was under review, and undertook that I would be contacted on completion of the review. The seven days allowed by clause 1.11.2(a) expired on 10 August 2026. No outcome of Stage 1 has ever been communicated to me.',B))
s.append(P('I earlier referred the matter to Stage 2 and withdrew that referral on 28 August 2026, in order to work through the issues directly with Ms Roberts. In doing so I withdrew the referral only, and recorded that my concerns regarding pay, the leave debited since 3 July 2026 and the adjustments in the Employee Capability Checklist of 3 July 2026 remained unresolved and in dispute. They remain unresolved, and the position has worsened since.',B))

s.append(P('<b>The matter can be put shortly.</b> I have been absent from the workplace since 3 July 2026 because I was directed not to attend. On each day of that absence a leave type has been selected and entered on my record on my behalf. Of the leave types available, three produce a payment and one does not. The one that does not has been selected on every day since 3 July 2026 — after I instructed in writing on that day that annual leave was to be applied; after every objection I have made since; and again on 4 August 2026, on the very day the Health Service itself identified the paid alternative and undertook to apply it. That is why I have not been paid.',B))
s.append(P('2. WHY THIS REFERRAL IS MADE TO YOU',H2))
s.append(P('Clause 1.11.2(b) requires the matter to be referred to "the appropriate management representative". Stage 1 was conducted with my immediate supervisor, as clause 1.11.2(a) provides. I refer Stage 2 to you because two of the matters in dispute cannot be decided below your office.',B))
s.append(P('<b>Special leave is a chief executive\'s power.</b> Directive 12/24, which applies to every employee covered by the Agreement through clause 9.12, provides at clause 6.1 that "a chief executive may approve paid leave for employees for any purpose", and at clause 6.5 that "in determining an application for leave under clause 6.1 or clause 6.2, a chief executive must consider" the reason for the leave, its duration, and the impact on the employee if it is not approved. Section 6 of HR Policy C13 records that the delegate for a decision of this kind is the officer listed in the HR Delegations Manual. I applied for special leave on full pay on 28 July and again on 5 August 2026. It has never been determined. No officer below your office, or your delegate under the HR Delegations Manual, is able to determine it.',B))
s.append(P('<b>A decision on special leave would resolve the immediate position on its own.</b> It is paid at full pay, and under Directive 12/24 it is not debited from any leave account. Granting it would therefore restore my income and leave my accrued entitlements intact. It would not require the Health Service to determine the leave coding, the hours at which leave has been applied, the long service leave eligibility date, or the basis of the direction that I not attend — each of which would remain in dispute and can be dealt with at the conference. It is the one decision in this matter that can be made now, by one office, and it requires no view to be taken on any of the others.',B))
s.append(P('<b>No instrument or officer has ever been identified for the direction that I not attend.</b> I asked for both in the Stage 1 process on 4 August 2026 and have asked since. The identification of the delegate and the instrument, or the making of a decision, sits at executive level.',B))
s.append(P('I do not ask that you convene the conference personally. If you nominate a representative to hold it and to decide the matters within their delegation, I will attend with them, and I ask only that the matters reserved to the chief executive be determined by you or by your delegate under the HR Delegations Manual.',B))
s.append(P('3. THE MATTERS IN DISPUTE',H2))
for n,txt in [('1','<b>Pay.</b> I have received no wages since 13 July 2026 — fifty-six days, and three pay days at nil: 29 July, 12 August and 26 August 2026. I have been ready, willing and available throughout, and certified fit with restrictions on the Health Service\'s own form since 3 July 2026.'),
 ('2','<b>The direction not to attend.</b> I have been held out of the workplace since 3 July 2026. I asked in the Stage 1 process on 4 August 2026 for the instrument authorising that direction, and have asked repeatedly since. It has never been identified, and no written decision returning me to work or declining to has ever been issued. The reason given for my continued absence has been the state of the medical evidence. My treating psychiatrist wrote to the Health Service with four questions between 13 and 19 August 2026 and, as at 5 September 2026, had received no response.'),
 ('3','<b>The leave coding, and how the payment became nil.</b> Each "Sick Leave – No Pay" entry is a positive act — a leave type selected from those available and submitted on my behalf. The alternatives were available, and they were known to the officer entering them: on 4 August 2026 Ms Taylor identified my recreation leave balance at 41.21 hours and undertook that, absent a response, she would apply it "to ensure you receive the available paid leave entitlement for this period". The pay advice for that fortnight records "NP Sick Leave" 76.00 hours and gross pay of $0.00. Section 6 of HR Policy C13 permits leave to be submitted on an employee\'s behalf only where the employee\'s request for leave "is documented in writing" and the supporting documents "are sourced and retained". My written requests are for annual leave (3 July 2026) and special leave on full pay (5 August 2026). There is no written request for sick leave without pay, and on 31 August 2026 I confirmed in terms that I was not applying for personal leave. My leave record shows these not as a single standing code but as <b>discrete daily requests, each separately entered and separately approved</b> — among them "SICK LEAVE - NO PAY (03.08.2026 - 03.08.2026)" and "SICK LEAVE - NO PAY (04.08.2026 - 04.08.2026)", each marked APPROVED. The second of those was entered for 4 August 2026 — the same day on which Ms Taylor wrote that she was required to process leave on my behalf, identified my recreation leave balance at 41.21 hours, and undertook to apply it. On that day four courses were open: annual leave, which I had requested on 3 July; recreation leave, which she had identified and undertaken to apply; special leave on full pay, which I requested the following morning; and, within the very category selected, paid sick leave, of which I held a balance. The course entered and approved was the unpaid variant — the only one of the four which produces no payment. I have at no point declined to be paid: on 5 August 2026 I declined only that the absence be funded out of my own accrued recreation leave, and asked in the same sentence that special leave on full pay be applied instead.'),
 ('4','<b>The entry of 30 August 2026.</b> The leave takings report provided to me on 4 September 2026 records, for 30 August 2026, a leave type of "Absent Without Leave" (AWOL_NP), 7.60 hours, approved. It is the only entry of that type in the report, which covers 25 March 2019 to 4 September 2026. On 31 August 2026 Ms Taylor wrote that she had applied "S/L and A/L in lieu of S/L for your absence from the workplace through an AVAC as requested, for the past fortnight 17th August 2026 - 30th August 2026 ... PRN 249 863 66". 30 August 2026 is the last day of that fortnight. I have at no time been absent without authority.'),
 ('5','<b>Special leave.</b> My application for special leave on full pay under Directive 12/24, made on 28 July and 5 August 2026, has been neither granted nor refused.'),
 ('6','<b>Hours.</b> Leave was applied on 31 August 2026 at "0.5 FTE". The last reduced-hours arrangement expired on 28 June 2026 and nothing replaced it. The Health Service\'s own Request for Medical Information of 31 July 2026 describes my employment as "Permanent Full-time (76 hours per fortnight)".'),
 ('7','<b>Long service leave.</b> On 4 September 2026 Payroll confirmed that I commenced on 25 March 2019 and that my long service leave eligibility would ordinarily arise on 25 March 2026, and advised a corrected date of 29 September 2026 after excluding three periods of leave without pay: 18 May to 10 June 2022; 21 June to 20 September 2024; and 13 December 2024 to 23 February 2025. My accrued balance is 342.5518 hours.<br/><br/>Three instruments give access to long service leave at seven years. Clause 22(c) of the Hospital and Health Service General Employees (Queensland Health) Award &ndash; State 2015 provides that "Employees who have completed 7 years&rsquo; continuous service are entitled to take long service leave on full pay or half pay". Clause 8.1 of Directive 10/24 provides that "employees are entitled to take pro rata long service leave after 7 years continuous service". Section 1 of HR Policy C38, to which clause 9.10.1 of the Agreement refers, provides that employees "may apply for pro rata long service leave on full pay, or half pay, after completing seven years continuous service". Seven years of continuous service fell on 25 March 2026.<br/><br/>I have read that chain for a provision excluding approved leave without pay from continuous service and have not found one. Section 94 of the <i>Industrial Relations Act 2016</i> applies Part 4 of the Act to long service leave, and section 134(3) provides that "An employee&rsquo;s continuity of service with an employer is not broken by an absence, including through illness or injury &mdash; (a) on paid leave approved by the employer; or (b) on unpaid leave approved by the employer". The leave takings report the Health Service produced on 4 September 2026 records 103 entries of leave without pay across the whole of my service, and every one of them is marked approved. Sixty-seven of those entries fall in the period 21 June to 20 September 2024, each recorded as leave category "Special", leave type "Leave Without Pay", status "APPROVED". The Health Service&rsquo;s own record therefore places every excluded day inside section 134(3)(b), not outside it. Where the Act intends a period not to count towards service it says so expressly, as it does for parental leave at section 90(2). If a provision exists which authorises the exclusion, I ask that it be identified. If there is none, my eligibility arose on 25 March 2026.<br/><br/>Separately, the agreement by which I was reinstated deals with one period of leave without pay, being 13 December 2024 to 23 February 2025, which the calculation applies. It does not deal with 21 June to 20 September 2024 in that way. It reserved those absences, and it reserved my position in relation to them. The Health Service then recorded them as approved leave without pay, which is the very absence section 134(3)(b) says does not break continuity of service. I also ask that the calculation be reconciled against my leave record, which records leave without pay on scattered days in May and June 2022 rather than as a continuous period, records the first such day in 2024 as 10 June, and records further such days between March 2025 and May 2026 which do not appear in the calculation.'),
 ('8','<b>Consultation and risk.</b> The workplace psychosocial risk assessment sought under clause 7.2 on 28 July 2026 has not been conducted, and the task-by-task match of the role description against the Employee Capability Checklist, sought the same day, has not been produced.')]:
    s.append(P(f'<b>{n}.</b>&nbsp;&nbsp;{txt}',BL))

s.append(P('4. THE AGREEMENT\'S REQUIREMENTS',H2))
s.append(P('<b>Clause 1.11.4</b> provides that "the status quo existing before the emergence of a dispute is to continue whilst the procedure is being followed". The status quo before 3 August 2026 was that I was employed, at 76 hours per fortnight, and paid. That has not been maintained: since the dispute was notified, my absence has been coded to a leave type that pays nothing, leave has been applied at half my hours, and my long service leave eligibility has been deferred.',B))
s.append(P('<b>Clause 1.11.5</b> provides that "no party shall act in a manner unreasonably or intentionally delay the timely resolution of a dispute".',B))
s.append(P('<b>Clause 1.11.2(b)</b> provides that the Stage 2 process "should not extend beyond seven days". I ask that the conference be arranged and held on or before <b>Monday 14 September 2026</b>.',B))

s.append(P('5. WHAT I SEEK',H2))
SEEK=[
 '''A determination of my application for special leave on full pay from 3 July 2026, by you or by your delegate under the HR Delegations Manual, in writing, with reasons addressing the considerations in clause 6.5 of Directive 12/24.''',
 '''Payment of the wages withheld since 13 July 2026; alternatively, the leave I have applied for entered without debit to my accrued credits, and the ad hoc payment pending under enquiry 4471091 processed against it.''',
 '''Correction of the leave coding from the first date it was applied, and before long service leave eligibility is recalculated in the leave audit opened on 3 September 2026.''',
 '''Correction of the entry of 30 August 2026 recorded as "Absent Without Leave", and identification of the basis on which it was made and the officer who made it.''',
 '''Leave and pay applied at 76 hours per fortnight, or the instrument relied on for any lesser figure.''',
 '''A written decision either returning me to work within the restrictions recorded on 3 July 2026 by a stated date, or declining to, identifying the instrument relied on and the officer who decided it.''',
 '''A copy of the written request and supporting documents on which each "Sick Leave – No Pay" entry since 3 July 2026 was made, as required by section 6 of HR Policy C13.''',
 '''Determination of my application for long service leave of 31 August 2026, as clause 7.4 of Directive 10/24 requires, and identification of the provision relied on to exclude any period from continuous service.''',
 '''The workplace psychosocial risk assessment sought under clause 7.2 on 28 July 2026, and the task-by-task match of the role description against the Employee Capability Checklist sought the same day.''',
]
for i,txt in enumerate(SEEK,1):
    s.append(P(f'<b>{i}.</b>&nbsp;&nbsp;{txt}',BL))
s.append(P('6. IF THE DISPUTE REMAINS UNRESOLVED',H2))
s.append(P('If the dispute is not resolved at Stage 2, I reserve my position under clause 1.11.2(c) to refer the matter to the EB12 Implementation Group, and under clause 1.11.2(d) to refer it to the Queensland Industrial Relations Commission.',B))
s.append(P('Everything I have applied for remains on the basis set out at paragraph 4 of my application of 31 August 2026 — under protest and subject to re-credit. I remain certified fit with restrictions and available to work.',B))
s.append(P('This notice concerns my employment only. My appeal in the Queensland Industrial Relations Commission is a separate proceeding and nothing in this notice forms part of it.',B))
s.append(Spacer(1,6))
s.append(P('<b>Attached, and forming part of this notice:</b> "The employment record — analysis, complete chronology and original documents". It sets out what the record shows, a chronology of every communication event on this matter from February to 3 September 2026, and behind it, in fifty-one tabs, the original documents themselves — the movement forms, the Employee Capability Checklist, the Request for Medical Information and its attachments, the Stage 1 notice and its acknowledgement, the pay advice, the payroll and leave records, and the whole of the correspondence. Nothing in it has been retyped. A supplement follows the record containing the two emails of 4 September 2026 by which the ad hoc payment and the long service leave calculation were advised. The leave takings report of 25 March 2019 to 4 September 2026, referred to above, was produced by the Health Service and is held by it.',B))
s.append(Spacer(1,8))
s.append(P('Cory Shepherd',B))
s.append(P('Employee number 388372 · 0417 400 227 · coryshepherd1@hotmail.com',SM))

buf=io.BytesIO()
doc=SimpleDocTemplate(buf,pagesize=A4,leftMargin=20*mm,rightMargin=20*mm,topMargin=16*mm,bottomMargin=15*mm,title='',author='')
doc.build(s); buf.seek(0)
out=pikepdf.open(buf)
with out.open_metadata() as md:
    for k in list(md): del md[k]
for k in list(out.docinfo.keys()): del out.docinfo[k]
r2=out.Root
for k in ('/Metadata','/PieceInfo','/Lang'):
    if k in r2: del r2[k]
for pg in out.pages:
    for k in ('/Metadata','/PieceInfo'):
        if k in pg.obj: del pg.obj[k]
out.save('out/NOTICE_OF_DISPUTE_STAGE2_to_CE_7SEP2026.pdf',fix_metadata_version=False)
print('dispute notice pages',len(out.pages))
